package com.nexusdrive.auth.service.impl;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.nexusdrive.auth.dto.RegisterRequest;import com.nexusdrive.auth.repository.*;import com.nexusdrive.common.config.JwtProperties;import com.nexusdrive.common.security.JwtTokenProvider;import org.junit.jupiter.api.Test;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;class AuthServiceImplTest{@Test void registrationHashesPasswordAndIssuesTokens(){var users=mock(UserRepository.class);var tokens=mock(RefreshTokenRepository.class);when(users.existsByUsernameIgnoreCaseOrEmailIgnoreCase(anyString(),anyString())).thenReturn(false);var p=new JwtProperties();p.setSecret("01234567890123456789012345678901");var service=new AuthServiceImpl(users,tokens,new BCryptPasswordEncoder(4),new JwtTokenProvider(p),p);var out=service.register(new RegisterRequest("alice","alice@example.com","strong-password"));assertNotNull(out.accessToken());verify(users).save(argThat(u->!u.getPasswordHash().equals("strong-password")));verify(tokens).save(any());}}
